// Tiny but real images for upload tests.
// JPEG: 2x1 pixels with only JFIF, tables and scan data (no metadata).
export const JPEG = Buffer.from(
  "",
  "base64",
);
// The same image as macOS sips wrote it, with an Exif (APP1) and a Photoshop/IPTC (APP13) block.
export const JPEG_FROM_SIPS = Buffer.from(
  "",
  "base64",
);
// PNG: 2x1 RGB (IHDR, IDAT, IEND).
export const PNG = Buffer.from(
  "iVBORw0KGgoAAAANSUhEUgAAAAIAAAABCAIAAAB7QOjdAAAAD0lEQVR4nGP4sEXj////AA/FBMptdw1eAAAAAElFTkSuQmCC",
  "base64",
);
// WebP: 1x1 lossless (RIFF + VP8L).
export const WEBP = Buffer.from("UklGRhoAAABXRUJQVlA4TA0AAAAvAAAAEAcQERGIiP4HAA==", "base64");

// A JPEG marker segment: 0xFF, marker, 16-bit length (including itself), payload.
export function jpegSegment(marker, payload) {
  const head = Buffer.from([0xff, marker, 0, 0]);
  head.writeUInt16BE(payload.length + 2, 2);
  return Buffer.concat([head, payload]);
}

// An APP1 Exif segment (little-endian) with an ImageDescription and an Orientation.
export function exifSegment({ orientation, description }) {
  const desc = Buffer.from(`${description}\0`, "latin1");
  const descAt = 8 + 2 + 2 * 12 + 4;
  const tiff = Buffer.alloc(descAt + desc.length);
  tiff.write("II", 0, "latin1");
  tiff.writeUInt16LE(42, 2);
  tiff.writeUInt32LE(8, 4);
  tiff.writeUInt16LE(2, 8);
  tiff.writeUInt16LE(0x010e, 10); // ImageDescription, ASCII
  tiff.writeUInt16LE(2, 12);
  tiff.writeUInt32LE(desc.length, 14);
  tiff.writeUInt32LE(descAt, 18);
  tiff.writeUInt16LE(0x0112, 22); // Orientation, SHORT
  tiff.writeUInt16LE(3, 24);
  tiff.writeUInt32LE(1, 26);
  tiff.writeUInt16LE(orientation, 30);
  desc.copy(tiff, descAt);
  return jpegSegment(0xe1, Buffer.concat([Buffer.from("Exif\0\0", "latin1"), tiff]));
}

// JPEG with the given segments inserted straight after its APP0 (JFIF) segment.
export const APP0_END = 20;
export function jpegWith(...segments) {
  return Buffer.concat([JPEG.subarray(0, APP0_END), ...segments, JPEG.subarray(APP0_END)]);
}
